description:
Design a simplified version of the ChaCha20 stream cipher's quarter round function in Verilog. This function takes four 32-bit inputs (a, b, c, d) and produces four 32-bit outputs (a_out, b_out, c_out, d_out) based on the ChaCha20 quarter round operation defined as follows:
1. a += b; d ^= a; d <<<= 16;
2. c += d; b ^= c; b <<<= 12;
3. a += b; d ^= a; d <<<= 8;
4. c += d; b ^= c; b <<<= 7;

Implement this operation as a clocked process where inputs are latched on the rising edge of a clock.

code:
module chacha20_quarter_round (
    input wire clk,
    input wire [31:0] a,
    input wire [31:0] b,
    input wire [31:0] c,
    input wire [31:0] d,
    output reg [31:0] a_out,
    output reg [31:0] b_out,
    output reg [31:0] c_out,
    output reg [31:0] d_out
);
    reg [31:0] a_reg, b_reg, c_reg, d_reg;

    always @(posedge clk) begin
        // Load inputs into registers
        a_reg <= a;
        b_reg <= b;
        c_reg <= c;
        d_reg <= d;

        // Perform the quarter round operations
        a_reg <= a_reg + b_reg; 
        d_reg <= d_reg ^ (a_reg << 16);

        c_reg <= c_reg + d_reg; 
        b_reg <= b_reg ^ (c_reg << 12);

        a_reg <= a_reg + b_reg; 
        d_reg <= d_reg ^ (a_reg << 8);

        c_reg <= c_reg + d_reg; 
        b_reg <= b_reg ^ (c_reg << 7);

        // Assign outputs
        a_out <= a_reg;
        b_out <= b_reg;
        c_out <= c_reg;
        d_out <= d_reg;
    end
endmodule

