    bluetooth_module dut (
        .clk(clk),
        .connection_success(connection_success),
        .reset(reset),
        .start_connect(start_connect),
        .state(state)
    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

        task reset_dut;

        begin
            reset = 1;
            start_connect = 0;
            connection_success = 0;
            @(posedge clk);
            #1 reset = 0;
            @(posedge clk);
        end
        endtask
    task testcase001;

        begin
            test_num = test_num + 1;
            $display("Test %0d: Initial IDLE state after reset", test_num);
            reset_dut();

            #1;


            check_outputs(2'b00);
        end
        endtask

    task testcase002;

        begin
            test_num = test_num + 1;
            $display("Test %0d: Transition IDLE to CONNECTING via start_connect", test_num);
            reset_dut();
            start_connect = 1;
            @(posedge clk);
            #1 start_connect = 0;
            @(posedge clk);
            #1;

            check_outputs(2'b01);
        end
        endtask

